function isNumber(t){return"number"==typeof t||"string"==typeof t&&/^\d*(\.\d*)?$/.test(t)}class Encryptor{constructor(){this.lastKeys=[]}get keyItems(){return this.lastTime||(this.lastTime=new Date,this.lastKeys=this.createKeys(this.lastTime)),this.lastKeys}getCurrentTime(){var t=null!=(t=this.lastTime)?t:new Date;return this.lastTime=void 0,`${t.getFullYear()}-${t.getMonth()+1}-${t.getDate()} ${t.getHours()}:${t.getMinutes()}:`+t.getSeconds()}encrypt(t){let r=this.keyItems;return window.btoa(t).split("").map((t,e)=>this.dictionaryCode(t.charCodeAt(0)-r[e%r.length])).join("")}decrypt(e,t){let r=0,i=0;for(var n=[],s=this.createKeys(t);r<e.length;){let t=1;this.isDictionaryCode(e.charAt(r))||t++,n.push(String.fromCharCode(this.dictionaryKey(e.substring(r,r+t)+s[i%s.length]))),r+=t,i++}return window.atob(n.join(""))}createKeys(t){isNumber(t)||(t="string"==typeof t?new Date(t):t)instanceof Date&&(t=Math.floor(t.getTime()/1e3));var e=t.toString().substring(0,10).split("").map(t=>parseInt(t)),r=e[e.length-1],i=r%2;for(let t=0;t<e.length;t+=2){var n=t+i;n>=e.length||(e[n]=(e[n]+r)%10)}return e}dictionaryLength(){return 51}dictionaryCode(t){var e=(t-=24)%this.dictionaryLength(),t=t>=this.dictionaryLength()?"0":"";return e<9?t+String.fromCharCode(49+e):e<35?t+String.fromCharCode(88+e):t+String.fromCharCode(30+e)}isDictionaryCode(t){return"0"!==t}dictionaryKey(t){let e=24,r=0;1<t.length&&(e+=this.dictionaryLength(),r=1);t=t.charCodeAt(r);return t<=57?e+t-49:t<=90?e+t-30:e+t-88}}